(6, 5, 'Doctor Prescription', 'TXT', '498 B', 'uploads/documents/b8fe333440cde9ad8545e999_prescription.txt', 'Medical Prescription', 'Internal Storage', 'IMPORTANT', 0, 0, 1, 'City Health Clinic Dr. R. Sharma MBBS MD\r\nPatient Name: Kishore Kumar Age: 24 Gender: Male\r\nDiagnosis: Acute Bronchitis and Viral Fever\r\nRx Medication:\r\n1. Amoxicillin 500mg - 1 tablet three times daily after food for 5 days\r\n2. Paracetamol 650mg - 1 tablet as needed for body ache and fever\r\n3. Levocetirizine 5mg - 1 tablet at night for allergic cough\r\nInstructions: Drink warm fluids, complete antibiotic course, follow up in 5 days.\r\nUrgent consultation required if breathing difficulty occurs.', '2026-10-28 05:47:00', '2026-10-28 05:47:00'),
(7, 5, 'Monthly Salary Slip', 'CSV', '486 B', 'uploads/documents/d8f17681ffafb4fed1c7e111_salary_slip.csv', 'Salary Slip', 'Internal Storage', 'IMPORTANT', 0, 0, 1, 'Field | Description | Amount INR\nCompany | Apex Technologies India Pvt Ltd\nEmployee Name | Kishore Kumar | Emp ID: APX4091\nPayslip For | Month of September 2024\nBasic Pay | Standard Component | 45000.00\nHRA | House Rent Allowance | 18000.00\nSpecial Allowance | Performance Allowance | 12000.00\nGross Earnings | Total Compensation | 75000.00\nPF Deduction | Provident Fund Contribution | 5400.00\nProfessional Tax | State Statutory Deduction | 200.00\nNet Salary | Disbursed to State Bank of India Account | 69400.00', '2026-10-28 05:47:00', '2026-10-28 05:47:00'),
(8, 5, 'Apartment Rental Agreement', 'JSON', '579 B', 'uploads/documents/b3b8151d5c05d79d0a3096c0_rental_agreement.json', 'Rental Agreement', 'Internal Storage', 'NORMAL', 0, 0, 1, 'document_type: Rental Agreement and Tenancy Contract\nstamp_duty: Non-Judicial Stamp Paper INR 100\nlandlord: Mr. S. Venkatraman\ntenant: Mr. Kishore Kumar\npremises: Flat 302, Green Valley Apartments, Anna Nagar, Chennai 600040\nmonthly_rent: INR 22,000 payable before 5th of each month\nsecurity_deposit: INR 100,000 refundable upon vacating premises\nlease_period: 11 Months commencing from October 1 2024\nmaintenance: Tenant shall pay monthly apartment association maintenance of INR 2500', '2026-10-28 05:47:00', '2026-10-28 05:47:00'),
(9, 5, 'AI Research Capstone Report', 'DOCX', '2.1 KB', 'uploads/documents/57f8ea760bce149f6dd78f53_research_project.docx', 'Project Report', 'Internal Storage', 'IMPORTANT', 0, 0, 3, 'IntelliFile: AI Powered On-Device Document Assistant Final Year Project Report\nDepartment of Computer Science and Engineering, Final Semester Project Documentation.\nAbstract: This project introduces a privacy-preserving document search and classification engine that runs locally on edge devices. Traditional file explorers only organize files by name and extension. IntelliFile integrates TF-IDF vector embeddings and multinomial Naive Bayes models to automatically classify incoming scans into Marksheets, Identity cards, and Assignments.\nMethodology: The system implements an extractive question answering pipeline that calculates cosine similarity between user queries and candidate document sentences. Results demonstrate 99% precision on structured Indian documents.\nSubmission deadline for final dissertation evaluation is due tomorrow.', '2026-10-28 05:47:00', '2026-10-28 05:47:00'),
(10, 5, 'Cloud Computing Lecture', 'PPTX', '1.5 KB', 'uploads/documents/dd88b0657cf5d618ac1f5caf_cloud_lecture.pptx', 'Notes', 'Internal Storage', 'NORMAL', 0, 0, 2, 'Slide 1: Cloud Computing Lecture Notes Chapter 4 Virtualization, Containers, and Docker Architecture study guide\n\nSlide 2: Key Topics: Amazon Web Services EC2 instances, S3 object storage buckets, and Kubernetes cluster orchestration. Exam revision notes: Containerization isolates application runtimes without hypervisor overhead.', '2026-10-28 05:47:00', '2026-10-28 05:47:00'),
(11, 5, 'SBI Bank Statement', 'XLSX', '1.3 KB', 'uploads/documents/236d937c4095bb2e4c711eb1_bank_statement.xlsx', 'Bank Statement', 'Internal Storage', 'IMPORTANT', 0, 0, 1, 'State Bank of India Account Statement, Savings Bank Account Number 30981245012 IFSC Code SBIN0001234 Branch Anna Nagar, Opening Balance INR 25400.00, Salary Credit NEFT INR 69400.00, UPI Payment to Swiggy Debit INR 450.00, Electricity Bill TNEB Debit INR 1250.00, Closing Available Balance INR 93100.00, Statement Generated on October 28 2024', '2026-10-28 05:47:00', '2026-10-28 05:47:00'),
